const char *agc_rc_message(agc_rc rc)
{
    switch (rc) {
    case AGC_OK: return "success";
    case AGC_ERR_UNSPECIFIED: return "no more specific code applies";
    case AGC_ERR_INVALID_ARGUMENT: return "NULL where required, bad length, bad enum";
    case AGC_ERR_BUFFER_TOO_SMALL: return "out_len holds the required size";
    case AGC_ERR_OUT_OF_MEMORY: return "allocation failure";
    case AGC_ERR_NOT_IMPLEMENTED: return "optional RPC not offered by this build";
    case AGC_ERR_INVALID_HANDLE: return "stale/foreign/freed handle";
    case AGC_ERR_ABI_MISMATCH: return "struct_size not recognised";
    case AGC_ERR_UNAVAILABLE: return "remote deployment mode: transport failure";
    case AGC_ERR_PERMISSION_DENIED: return "caller identity lacks the IAM scope";
    case AGC_ERR_ALREADY_EXISTS: return "duplicate name where uniqueness is required";
    case AGC_ERR_CANCELLED: return "operation cancelled by the caller";
    case AGC_ERR_DEADLINE_EXCEEDED: return "remote deployment mode: timed out";
    case AGC_ERR_INTERNAL: return "unexpected internal condition";
    case AGC_ERR_PROVIDER_CONTRACT_VIOLATION: return "e.g. unset ProviderOutput.algorithm_output";
    case AGC_ERR_ITERATOR_EXHAUSTED: return "normal end of a list iteration";
    default: return "unknown result code";
    }
}
